"""Summarize node sequence gaps without changing the node."""
import argparse
import json
import os
from pathlib import Path
import re
import stat


CHANNELS = ("obs", "must")


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def record_names(folder, channel):
    numbered = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl\Z")
    selected = []
    with os.scandir(folder) as entries:
        for entry in entries:
            if not entry.is_file(follow_symlinks=False):
                continue
            match = numbered.fullmatch(entry.name)
            if match:
                selected.append(((0, int(match.group(1))), entry.name))
            elif entry.name == channel + ".active.jsonl":
                selected.append(((1, 0), entry.name))
    return [name for _, name in sorted(selected)]


def read_records(folder, channel, bad):
    seqs = []
    for name in record_names(folder, channel):
        data = (folder / name).read_bytes()
        lines = data.split(b"\n")
        for number, line in enumerate(lines, 1):
            if number == len(lines):
                if line:
                    bad.append({"file": name, "line": number, "why": "torn"})
                continue
            try:
                obj = json.loads(line.decode("utf-8"), parse_constant=reject_constant)
            except (UnicodeError, ValueError):
                bad.append({"file": name, "line": number, "why": "bad_json"})
                continue
            if not isinstance(obj, dict) or type(obj.get("seq")) is not int or obj["seq"] < 1:
                bad.append({"file": name, "line": number, "why": "no_seq"})
                continue
            seqs.append(obj["seq"])
    return seqs


def read_state(folder, bad):
    path = folder / "state.json"
    result = {channel: None for channel in CHANNELS}
    try:
        mode = path.lstat().st_mode
    except FileNotFoundError:
        return result
    except OSError:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return result
    try:
        if not stat.S_ISREG(mode):
            raise ValueError("state is not a regular file")
        state = json.loads(path.read_bytes().decode("utf-8"), parse_constant=reject_constant)
        if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
            raise ValueError("invalid channels")
    except (OSError, UnicodeError, ValueError):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return result
    invalid = False
    for channel in CHANNELS:
        part = state["channels"].get(channel)
        if not isinstance(part, dict) or type(part.get("next_seq")) is not int:
            invalid = True
        elif channel == "must" and type(part.get("acked_upto")) is not int:
            invalid = True
        else:
            result[channel] = part
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    return result


def summarize(folder):
    bad = []
    records = {channel: read_records(folder, channel, bad) for channel in CHANNELS}
    state = read_state(folder, bad)
    channels = {}
    for channel in CHANNELS:
        seqs = records[channel]
        unique = sorted(set(seqs))
        first = unique[0] if unique else None
        last = unique[-1] if unique else None
        part = state[channel]
        channels[channel] = {
            "count": len(seqs),
            "first": first,
            "last": last,
            "missing": [[a + 1, b - 1] for a, b in zip(unique, unique[1:]) if b > a + 1],
            "dup": sorted(seq for seq in unique if seqs.count(seq) >= 2),
            "next_seq": part["next_seq"] if part is not None else None,
            "unacked": (sum(seq > part["acked_upto"] for seq in unique)
                        if channel == "must" and part is not None else None),
            "stale_next": (part["next_seq"] != last + 1
                           if part is not None and last is not None else None),
        }
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only node sequence summary")
    parser.add_argument("folder", type=Path)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    print(json.dumps(summarize(args.folder), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
